 	if (code === "WRITER_HOLD") return "stop-unconfirmed";
 	if (e?.name === "DelegationAborted" || e?.name === "AbortError") return "cancel";
 	const operation = tool === "planner_delegate" || tool === "planner_redelegate" ? "delegation" : tool;
